/* ---------- SRC-30.4 · STORM GARDEN V4 (aim the lines, play the clouds, strike to grow) ---------- */
(() => {
// REAL ASSETS, inlined: Lance's 3 storm clouds, forked lightning (decimated),
// stalked jellyfish stauromedusae (decimated), low-poly tree pack (decimated)
const SG4_CLOUDS = ['', '', ''];
const SG4_JELLY = '';
const SG4_TREES = '';
const SG4 = { sky: 0x070512, mass: 0x252045, warm: 0xff8a3d, gold: 0xffd9a0, heart: 0xd9c8ff, teal: 0x4fd8c4, vio: 0xa06cff };
// five clouds, five instruments — the band you AIM at
const SG4_DEFS = [
  { name: 'EMBER',  gx: -0.72, y: 0.55, glb: 0, s: 0.55, col: SG4.warm,  role: 'arp',     intv: [0.5, 0.25, 0.25], lad: [0, 1, 2, 1], oct: 0 },
  { name: 'GOLD',   gx: -0.36, y: 0.67, glb: 1, s: 0.62, col: SG4.gold,  role: 'lead',    intv: [0.75, 0.5, 0.25], lad: [2, 4, 3, 0], oct: 1 },
  { name: 'HEART',  gx: 0.0,   y: 0.60, glb: 2, s: 0.85, col: SG4.heart, role: 'bass',    intv: [1, 0.5, 0.5],     lad: [0, 0, 2, 0], oct: -1 },
  { name: 'TIDE',   gx: 0.36,  y: 0.67, glb: 1, s: 0.58, col: SG4.teal,  role: 'bells',   intv: [0.5, 0.25, 0.25], lad: [3, 1, 4, 2], oct: 1 },
  { name: 'VESPER', gx: 0.72,  y: 0.55, glb: 0, s: 0.55, col: SG4.vio,   role: 'texture', intv: [2, 1, 0.5],       lad: [4, 2, 0, 3], oct: 2 }
];
reg({
  id: 'SRC-30.4', family: 'SRC-30', ver: 5,
  title: 'Storm Garden V4', tech: 'AIMED LINES / FIVE-CLOUD BAND',
  music: {
    bpm: 88, root: 48, mode: 'aeolian', chordBars: 2,
    chords: [
      [0, 15, 19, 20, 22],
      [0, 7, 8, 15, 26],
      [0, 10, 15, 17, 26],
      [0, 7, 10, 15, 22]
    ],
    chordNames: ['Cm7♭13', 'Cm9♭13', 'Cm11', 'Cm7']
  },
  fx: { bloom: 0.5 },
  tags: ['AIM A CLOUD, PLAY ITS GROOVE', 'CHARGE → STRIKE → RELEASE', 'STRIKES GROW THE JELLIES', 'REAL ASSETS'],
  desc: 'Five storm clouds hang over a dark treeline, and every one is a different instrument: EMBER plucks warm eighths, GOLD lopes in dotted phrases, HEART is the deep pulse, TIDE showers bell sixteenths, VESPER tolls long violet chimes. Two vertical lines of light stand at the center of the sky — your hands AIM them. Park a line under a cloud and it wakes: its groove starts, pulses climb its column and land as notes, rain falls fat and glowing. STAY on it and it charges — the pulses double, then double again, the glow builds — until the cloud releases: real forked lightning to the ground, a full-frame flash, thunder. Strike the same ground twice and a stalked jellyfish sprouts from the soaked earth — the real scanned stauromedusae, glowing, swaying, adding its voice to the drone. Strike enough places and you grow a garden.',
  interact: 'Hands down: both selector lines rest at center. RAISE L to sweep its line out across the left sky, R across the right — park a line under a cloud to SELECT it and its groove plays. HOLD to charge: pulse rate climbs whole→eighths→sixteenths, always on the grid; full charge = lightning + release, and that cloud rests a moment. BOTH lines on one cloud charges it double-speed. Each strike soaks the ground below — two strikes in one place grow a jellyfish (six max). Different clouds = different grooves: aim two at once and you are a band.',
  sound: 'C-minor pedal (blur chords) under everything: sub root, soft triangle bed, one voice per grown jellyfish. Each cloud owns a role and channel — EMBER plucks (arp ch4), GOLD dotted keys (lead ch1), HEART pulse bass (ch3), TIDE bells (ch5), VESPER chimes (texture ch6, where your thunder samples also live — strikes send a long low C). Charge = rising storm rumble. No groove plays unless a line is parked on its cloud: silence is the default, weather is earned. CC74 per role = that cloud\'s energy.',
  init(P) {
    const s = P.state = {
      pres: 0, eL: 0, eR: 0, pL: 0, pR: 0, vel: 0,
      selL: -1, selR: -1, lineL: 0, lineR: 0,
      charge: SG4_DEFS.map(() => 0), spent: SG4_DEFS.map(() => 0),
      strikePend: -1, strikeAt: 0, strikeCloud: -1,
      flashA: 0, boltT: 0, boltX: 0,
      spots: [], jellies: [], sproutReq: [], drops: [],
      land: SG4_DEFS.map(() => 0), idleT: 0, strikes: 0
    };
    if (typeof THREE === 'undefined') { s.noGL = true; return; }
    if (P._three) { try { P._three.renderer.dispose(); } catch (e) {} }
    const T3 = {}; P._three = T3;
    const r = new THREE.WebGLRenderer({ antialias: false });
    r.setSize(P.w, P.h, false);
    r.setClearColor(SG4.sky, 1);
    T3.renderer = r;
    const A2 = P.w / Math.max(1, P.h);
    T3.A = A2;
    const sc = new THREE.Scene();
    const cam = new THREE.OrthographicCamera(-A2, A2, 1, -1, 0.1, 10);
    cam.position.z = 2;
    T3.scene = sc; T3.cam = cam;
    sc.add(new THREE.AmbientLight(0x8878b0, 0.5));
    const key = new THREE.DirectionalLight(0xbfa9ff, 0.9);
    key.position.set(0.3, -0.5, 1); // storm-lit: light rakes the undersides
    sc.add(key);
    const GROUND_Y = -0.78;
    T3.GROUND_Y = GROUND_Y;

    const glowMat = (col) => new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
      uniforms: { uCol: { value: new THREE.Color(col) }, uI: { value: 1 } },
      vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
      fragmentShader: 'uniform vec3 uCol; uniform float uI; varying vec2 vUv; void main(){ float d = length(vUv - 0.5) * 2.0; float g = exp(-d*d*3.2); gl_FragColor = vec4(uCol * g * uI, 1.0); }'
    });
    T3.glowMat = glowMat;
    const colMat = (col) => new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
      uniforms: { uCol: { value: new THREE.Color(col) }, uI: { value: 0 }, uPh: { value: 0 }, uT: { value: 0 }, uFlash: { value: 0 } },
      vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
      fragmentShader: [
        'uniform vec3 uCol; uniform float uI, uPh, uT, uFlash; varying vec2 vUv;',
        'void main(){',
        '  float edge = smoothstep(0.0, 0.30, vUv.x) * smoothstep(1.0, 0.70, vUv.x);',
        '  float vfade = smoothstep(0.0, 0.16, vUv.y) * smoothstep(1.02, 0.72, vUv.y);',
        '  float st = fract(vUv.y * 5.0 + uT * (1.0 + 2.0 * uI));',
        '  float streak = smoothstep(0.0, 0.3, st) * smoothstep(0.7, 0.35, st);',
        '  float base = (0.03 + 0.32 * uI) * edge * vfade * (0.55 + 0.45 * streak);',
        '  float p = exp(-pow((vUv.y - uPh) / 0.07, 2.0)) * min(uI * 3.0, 1.0) * edge;',
        '  vec3 c = uCol * base + uCol * p * 1.15 + vec3(1.0) * p * 0.38 + uCol * uFlash * edge * vfade;',
        '  gl_FragColor = vec4(c, 1.0);',
        '}'
      ].join('\n')
    });

    const b64buf = b => Uint8Array.from(atob(b), ch => ch.charCodeAt(0)).buffer;
    const loader = typeof THREE.GLTFLoader === 'function' ? new THREE.GLTFLoader() : null;
    const fitWrap = (m, target) => {
      m.updateMatrixWorld(true);
      const bb = new THREE.Box3().setFromObject(m);
      const size = bb.getSize(new THREE.Vector3());
      const c0 = bb.getCenter(new THREE.Vector3());
      const f = target / Math.max(size.x, size.y, size.z, 0.001);
      m.position.sub(c0);
      const wrap = new THREE.Group();
      wrap.add(m); wrap.scale.setScalar(f);
      return wrap; // animate the WRAP, never the centered child
    };

    // ---- five clouds from the REAL models — flat-shaded, storm-lit facets ----
    T3.clouds = [];
    SG4_DEFS.forEach((d, ci) => {
      const grp = new THREE.Group();
      grp.position.set(d.gx * A2, d.y, 0);
      sc.add(grp);
      const glow = new THREE.Mesh(new THREE.PlaneGeometry(1, 0.4), glowMat(d.col));
      glow.position.set(0, -0.16 * d.s - 0.06, 0.12);
      glow.scale.setScalar(d.s * 1.35);
      grp.add(glow);
      const mat = new THREE.MeshLambertMaterial({ color: SG4.mass, emissive: new THREE.Color(d.col).multiplyScalar(0.10), flatShading: true });
      const c = { grp, glow, def: d, mat, bob: ci * 1.7 };
      T3.clouds.push(c);
      const addFallback = () => {
        const g2 = new THREE.Group();
        [[0, 0, 0.5], [-0.42, -0.08, 0.34], [0.42, -0.06, 0.36]].forEach(b => {
          g2.add(new THREE.Mesh(new THREE.SphereGeometry(b[2], 7, 5), mat).translateX(b[0]).translateY(b[1]));
        });
        g2.scale.setScalar(d.s * 0.8); grp.add(g2); c.mass = g2;
      };
      if (loader) {
        try {
          loader.parse(b64buf(SG4_CLOUDS[d.glb]), '', gl2 => {
            try {
              const m = gl2.scene;
              m.traverse(o => { if (o.isMesh) o.material = mat; });
              const wrap = fitWrap(m, 1.6);
              wrap.scale.multiplyScalar(d.s);
              if (ci > 2) wrap.scale.x *= -1; // flip reused variants
              grp.add(wrap); c.mass = wrap;
            } catch (e) { addFallback(); }
          }, addFallback);
        } catch (e) { addFallback(); }
      } else addFallback();
      // one column per cloud — lights only when SELECTED
      const cm = colMat(d.col);
      const top = d.y - 0.16, h = top - GROUND_Y;
      const q = new THREE.Mesh(new THREE.PlaneGeometry(0.13, h), cm);
      q.position.set(d.gx * A2, GROUND_Y + h / 2, -0.1);
      sc.add(q);
      c.colMat = cm; c.topY = top;
    });

    // ---- treeline from the REAL pack — dark silhouettes along the ground ----
    if (loader) {
      try {
        loader.parse(b64buf(SG4_TREES), '', gl2 => {
          try {
            const treeMat = new THREE.MeshLambertMaterial({ color: 0x0e0b20, emissive: 0x140f2e, flatShading: true });
            [[-0.85, 0.34, 1], [-0.45, 0.26, -1], [0.18, 0.30, 1], [0.62, 0.38, -1], [0.95, 0.24, 1]].forEach(td => {
              const inst = gl2.scene.clone(true);
              inst.traverse(o => { if (o.isMesh) o.material = treeMat; });
              const wrap = fitWrap(inst, 1);
              wrap.scale.multiplyScalar(td[1]);
              wrap.scale.x *= td[2];
              wrap.position.set(td[0] * A2, GROUND_Y + td[1] * 0.34, -0.3);
              sc.add(wrap);
            });
          } catch (e) {}
        }, () => {});
      } catch (e) {}
    }


    // ---- jellyfish factory: the REAL stauromedusae, tinted and glowing ----
    T3.jellySrc = null;
    if (loader) {
      try {
        loader.parse(b64buf(SG4_JELLY), '', gl2 => { T3.jellySrc = gl2.scene; }, () => {});
      } catch (e) {}
    }
    T3.mkJelly = (x, col) => {
      const g2 = new THREE.Group();
      const jm = new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
      if (T3.jellySrc) {
        const inst = T3.jellySrc.clone(true);
        inst.traverse(o => { if (o.isMesh) o.material = jm; });
        const wrap = fitWrap(inst, 0.42);
        wrap.position.y = 0.20;
        g2.add(wrap);
      } else {
        const bell = new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 5, 0, Math.PI * 2, 0, Math.PI / 2), jm);
        bell.position.y = 0.3; g2.add(bell);
        const stalk = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.014, 0.3, 6), new THREE.MeshBasicMaterial({ color: 0x16122c }));
        stalk.position.y = 0.15; g2.add(stalk);
      }
      const core = new THREE.Mesh(new THREE.PlaneGeometry(0.3, 0.3), T3.glowMat(col));
      core.position.y = 0.24; g2.add(core);
      g2.position.set(x, GROUND_Y, 0.2);
      g2.scale.setScalar(0.001);
      sc.add(g2);
      return { grp: g2, jm, core, x, born: 0, life: 1, pulse: 0, sway: Math.random() * 6 };
    };
    // wet-spot markers
    T3.spotMat = [];
    T3.mkSpot = (x) => {
      const m = new THREE.MeshBasicMaterial({ color: 0x8f7bff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false });
      const q = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.045), m);
      q.position.set(x, GROUND_Y, 0.1);
      sc.add(q); return m;
    };
  },
  step(P, dt, t, inp) {
    const s = P.state;
    if (s.noGL) return;
    const T3 = P._three, A2 = T3 ? T3.A : 1.6;
    const live = (chan.L.mode === 'live' || chan.R.mode === 'live') ? 1 : 0;
    s.pres += (live - s.pres) * Math.min(1, dt * 1.5);
    const tL = clamp(inp.L), tR = clamp(inp.R);
    s.vel = s.vel * Math.max(0, 1 - dt * 2.2) + (Math.abs(tL - s.pL) + Math.abs(tR - s.pR)) * 6;
    s.pL = tL; s.pR = tR;
    s.eL += (tL - s.eL) * Math.min(1, dt * 28);
    s.eR += (tR - s.eR) * Math.min(1, dt * 28);
    if (s.pres < 0.12) { s.idleT += dt; } else s.idleT = 0;

    // V2's verb: lines rest at center, raising a hand sweeps its line outward
    s.lineL = -s.eL * (A2 - 0.14);
    s.lineR = s.eR * (A2 - 0.14);
    const pick = (lx, active) => {
      if (!active) return -1;
      let best = -1, bd = 0.26 * A2 / 1.6;
      SG4_DEFS.forEach((d, i) => {
        const dx = Math.abs(d.gx * A2 - lx);
        if (dx < bd) { bd = dx; best = i; }
      });
      return best;
    };
    s.selL = pick(s.lineL, s.eL > 0.08 && s.pres > 0.15);
    s.selR = pick(s.lineR, s.eR > 0.08 && s.pres > 0.15);

    // charge the selected clouds (same cloud with both lines = double speed)
    SG4_DEFS.forEach((d, i) => {
      s.spent[i] = Math.max(0, s.spent[i] - dt);
      const selCount = (s.selL === i ? 1 : 0) + (s.selR === i ? 1 : 0);
      if (selCount > 0 && s.spent[i] <= 0) {
        s.charge[i] = Math.min(1, s.charge[i] + dt * 0.11 * selCount);
        if (s.charge[i] >= 1 && s.strikePend < 0) { s.strikePend = i; }
      } else {
        s.charge[i] = Math.max(0, s.charge[i] - dt * 0.22);
      }
    });

    // strike lands when its scheduled moment arrives
    if (s.strikeAt && typeof AE !== 'undefined' && AE.ctx && AE.t() >= s.strikeAt) {
      s.strikeAt = 0;
      const ci = s.strikeCloud;
      const cx = SG4_DEFS[ci].gx * A2;
      s.flashA = 1; s.boltT = 0.42; s.boltX = cx;
      s.strikes++;
      // soak the ground: find or make a wet spot; two soaks = a jellyfish
      let spot = s.spots.find(sp => Math.abs(sp.x - cx) < 0.3);
      if (!spot) { spot = { x: cx + (Math.random() - 0.5) * 0.14, amt: 0, mat: T3 ? T3.mkSpot(cx) : null }; s.spots.push(spot); }
      spot.amt += 1;
      if (spot.amt >= 1.75 && s.jellies.filter(j => j.life > 0).length < 6) {
        spot.amt = 0.4;
        s.sproutReq.push(spot.x + (Math.random() - 0.5) * 0.2);
      }
    }
    s.flashA = Math.max(0, s.flashA - dt * 2.6);
    s.boltT = Math.max(0, s.boltT - dt);
    SG4_DEFS.forEach((d, i) => { s.land[i] = Math.max(0, s.land[i] - dt * 5); });
    for (const sp of s.spots) sp.amt = Math.max(0, sp.amt - dt * 0.01);
    for (const j of s.jellies) {
      j.born = Math.min(1, j.born + dt * 2.0);
      j.pulse = Math.max(0, j.pulse - dt * 3.2);
      if (s.idleT > 40) j.life = Math.max(0, j.life - dt * 0.1);
    }
  },
  draw(P, g, w, h, t, inp) {
    const s = P.state;
    if (s.noGL || !P._three) {
      g.fillStyle = '#070512'; g.fillRect(0, 0, w, h);
      g.fillStyle = 'rgba(180,170,220,0.75)'; g.font = `${Math.max(10, h * 0.03)}px ui-monospace,monospace`;
      g.textAlign = 'center';
      g.fillText('STORM GARDEN V4 · AIM THE LINES, PLAY THE CLOUDS', w / 2, h / 2 - 12);
      g.fillText('open on the hosted site (WebGL)', w / 2, h / 2 + 14);
      g.textAlign = 'left';
      return;
    }
    const T3 = P._three, A2 = T3.A, GROUND_Y = T3.GROUND_Y;
    const beats = (typeof T !== 'undefined' && T.running) ? T.beats() : t * 1.4;
    T3.clouds.forEach((c, ci) => {
      const d = c.def;
      const sel = (s.selL === ci || s.selR === ci) && s.spent[ci] <= 0;
      const ch = s.charge[ci];
      c.grp.position.y = d.y + Math.sin(t * 0.3 + c.bob) * 0.012;
      const swell = 1 + ch * 0.22 + (ci === s.strikeCloud ? s.flashA * 0.12 : 0);
      if (c.mass) {
        if (!c.fitS) c.fitS = Math.abs(c.mass.scale.y); // capture the fitted scale once
        const k = c.fitS * swell;
        c.mass.scale.set((ci > 2 ? -k : k), k, k);
      }
      const spentDim = s.spent[ci] > 0 ? 0.25 : 1;
      c.mat.emissive.set(d.col).multiplyScalar((0.08 + (sel ? 0.22 : 0) + ch * 0.5 + (ci === s.strikeCloud ? s.flashA * 0.8 : 0)) * spentDim);
      c.glow.material.uniforms.uI.value = (0.18 + (sel ? 0.8 : 0) + ch * 1.6 + (ci === s.strikeCloud ? s.flashA * 2.0 : 0)) * spentDim;
      const u = c.colMat.uniforms;
      u.uT.value = t;
      const lvl = ch < 0.34 ? 0 : ch < 0.72 ? 1 : 2;
      const intv = d.intv[lvl];
      u.uI.value = sel ? 0.35 + ch * 0.65 : 0;
      u.uPh.value = ((beats / intv) % 1 + 1) % 1;
      u.uFlash.value = (ci === s.strikeCloud ? s.flashA : s.land[ci] * (sel ? 0.5 : 0)) * 0.9;
    });
    // wet spots
    s.spots.forEach(sp => { if (sp.mat) sp.mat.opacity = Math.min(1, sp.amt / 2) * 0.5; });
    // jellies
    for (const j of s.jellies) {
      const k = j.born * j.life;
      j.grp.scale.setScalar(Math.max(0.001, k * (1 + j.pulse * 0.08)));
      j.grp.rotation.z = Math.sin(t * 0.7 + j.sway) * 0.07;
      j.jm.opacity = 0.5 * j.life + j.pulse * 0.28;
      j.core.material.uniforms.uI.value = 0.3 + j.pulse * 1.3;
    }
    T3.renderer.render(T3.scene, T3.cam);
    g.clearRect(0, 0, w, h);
    g.drawImage(T3.renderer.domElement, 0, 0, w, h);

    const ms = Math.max(1, Math.sqrt(areaScale(P)));
    const wx = x => (x / A2 + 1) * 0.5 * w;
    const wy = y => (1 - (y + 1) * 0.5) * h;
    // fat rain under selected clouds
    const spawnRain = ci => {
      const c = T3.clouds[ci], d = c.def;
      const inten = 0.4 + s.charge[ci] * 0.6;
      for (let i = 0; i < 2; i++) {
        if (Math.random() > inten * 0.8) continue;
        s.drops.push({ x: d.gx * A2 + (Math.random() - 0.5) * 0.12, y: c.topY - Math.random() * 0.2, v: 1.5 + inten, col: '#' + new THREE.Color(d.col).getHexString(), w: (2.6 + inten * 2.8) * ms });
      }
    };
    if (s.selL >= 0 && s.spent[s.selL] <= 0) spawnRain(s.selL);
    if (s.selR >= 0 && s.selR !== s.selL && s.spent[s.selR] <= 0) spawnRain(s.selR);
    g.lineCap = 'round';
    for (let i = s.drops.length - 1; i >= 0; i--) {
      const d = s.drops[i];
      d.y -= d.v * 0.016;
      if (d.y <= GROUND_Y) { s.drops.splice(i, 1); continue; }
      g.strokeStyle = d.col; g.globalAlpha = 0.4; g.lineWidth = d.w;
      g.beginPath(); g.moveTo(wx(d.x), wy(d.y)); g.lineTo(wx(d.x), wy(d.y + 0.13)); g.stroke();
    }
    g.globalAlpha = 1;
    if (s.drops.length > 220) s.drops.splice(0, s.drops.length - 220);
    // THE SELECTOR LINES — V2's verb, verbatim: two vertical lines you aim
    const drawLine = (x, col, sel) => {
      const px = wx(x);
      g.strokeStyle = col; g.globalAlpha = 0.75;
      g.lineWidth = 4.5 * ms;
      g.beginPath(); g.moveTo(px, h * 0.06); g.lineTo(px, wy(GROUND_Y)); g.stroke();
      g.globalAlpha = 0.22; g.lineWidth = 13 * ms;
      g.beginPath(); g.moveTo(px, h * 0.06); g.lineTo(px, wy(GROUND_Y)); g.stroke();
      g.globalAlpha = 1;
      if (sel >= 0) { // bracket the captured cloud
        const cx = wx(SG4_DEFS[sel].gx * A2), cy = wy(SG4_DEFS[sel].y);
        g.strokeStyle = col; g.lineWidth = 3 * ms; g.globalAlpha = 0.9;
        const bw = 46 * ms;
        g.beginPath();
        g.moveTo(cx - bw, cy - bw * 0.5); g.lineTo(cx - bw, cy - bw * 0.8); g.lineTo(cx - bw * 0.7, cy - bw * 0.8);
        g.moveTo(cx + bw, cy - bw * 0.5); g.lineTo(cx + bw, cy - bw * 0.8); g.lineTo(cx + bw * 0.7, cy - bw * 0.8);
        g.stroke(); g.globalAlpha = 1;
      }
    };
    if (s.pres > 0.12) {
      drawLine(s.lineL, '#ff8a3d', s.selL);
      drawLine(s.lineR, '#a06cff', s.selR);
    }
    // THE STRIKE: fat forked 2D bolt from the struck cloud to the ground
    if (s.boltT > 0) {
      if (!s.bolt) {
        const topY = s.strikeCloud >= 0 ? SG4_DEFS[s.strikeCloud].y - 0.1 : 0.55;
        const pts = [[s.boltX, topY]]; let x = s.boltX;
        for (let y = topY; y > GROUND_Y; y -= 0.12) { x += (Math.random() - 0.5) * 0.2; pts.push([x, y]); }
        pts.push([x, GROUND_Y]);
        const fork = pts.slice(0, 4 + (Math.random() * 3 | 0)).map(p => [...p]);
        let fx = fork[fork.length - 1][0];
        for (let y = fork[fork.length - 1][1]; y > GROUND_Y + 0.3; y -= 0.14) { fx += (Math.random() < 0.5 ? -1 : 1) * 0.11; fork.push([fx, y]); }
        s.bolt = { pts, fork };
      }
      const flick = 0.55 + Math.random() * 0.45;
      const seg = (pts, wGlow, wCore) => {
        g.beginPath(); pts.forEach((p, i) => i ? g.lineTo(wx(p[0]), wy(p[1])) : g.moveTo(wx(p[0]), wy(p[1])));
        g.strokeStyle = 'rgba(160,108,255,' + 0.5 * flick + ')'; g.lineWidth = wGlow * ms; g.stroke();
        g.beginPath(); pts.forEach((p, i) => i ? g.lineTo(wx(p[0]), wy(p[1])) : g.moveTo(wx(p[0]), wy(p[1])));
        g.strokeStyle = 'rgba(245,240,255,' + 0.9 * flick + ')'; g.lineWidth = wCore * ms; g.stroke();
      };
      seg(s.bolt.pts, 26, 9);
      seg(s.bolt.fork, 16, 5);
    } else s.bolt = null;
    if (s.flashA > 0.01) {
      g.fillStyle = 'rgba(233,224,255,' + (s.flashA * 0.8) + ')';
      g.fillRect(0, 0, w, h);
    }
    const selName = i => i >= 0 ? SG4_DEFS[i].name : '—';
    const maxCh = Math.max(...s.charge);
    const alive = s.jellies.filter(j => j.life > 0.05).length;
    g.fillStyle = 'rgba(200,190,215,0.75)'; g.font = `${Math.round(10 * ms)}px ui-monospace,monospace`;
    g.fillText('L▸' + selName(s.selL) + '  R▸' + selName(s.selR) + '  ·  CHARGE ' + Math.round(maxCh * 100) + '%  ·  STRIKES ' + s.strikes + '  ·  JELLIES ' + alive + '/6  ·  ' + (H.label || '') + (s.pres < 0.3 ? '  ·  SLEEPING' : ''), 10, h - 10);
  },
  audio(A, P) {
    const v = A.voice();
    const sub = v.osc('sine', H.chordTone(0, -1));
    const subG = v.g(0.030); sub.connect(subG); subG.connect(v.group);
    const bed = [1, 3].map(i => {
      const o = v.osc('triangle', H.chordTone(i, 0));
      const gg = v.g(0.006); o.connect(gg); gg.connect(v.group);
      return { o, i };
    });
    const jellyV = [];
    for (let i = 0; i < 6; i++) {
      const o = v.osc('triangle', H.chordTone(2 + i, i < 3 ? 0 : 1));
      const gg = v.g(0.0001);
      const pan = A.ctx.createStereoPanner ? A.ctx.createStereoPanner() : null;
      if (pan) { o.connect(gg); gg.connect(pan); pan.connect(v.group); }
      else { o.connect(gg); gg.connect(v.group); }
      jellyV.push({ o, gg, pan, idx: 2 + i, oct: i < 3 ? 0 : 1 });
    }
    const nsrc = A.ctx.createBufferSource(); nsrc.buffer = A.noiseBuf(); nsrc.loop = true;
    const nLP = A.ctx.createBiquadFilter(); nLP.type = 'lowpass'; nLP.frequency.value = 90; nLP.Q.value = 0.6;
    const nG = A.ctx.createGain(); nG.gain.value = 0.0001;
    nsrc.connect(nLP); nLP.connect(nG); nG.connect(v.group); nsrc.start();
    if (A.revIn) { const s2 = A.ctx.createGain(); s2.gain.value = 0.5; v.group.connect(s2); s2.connect(A.revIn); }
    H.onChord(() => {
      A.set(sub.frequency, H.chordTone(0, -1), 0.25);
      bed.forEach(b => A.set(b.o.frequency, H.chordTone(b.i, 0), 0.2));
      jellyV.forEach(p => A.set(p.o.frequency, H.chordTone(p.idx, p.oct), 0.2));
    });
    v.fadeIn(1, 1.4);
    let nextT = T.next(0.25), step16 = 0;
    const ladPos = SG4_DEFS.map(() => 0);
    return {
      tick(inp) {
        const s = P.state;
        s.jellies.forEach((j, i) => {
          if (i < 6) {
            A.set(jellyV[i].gg.gain, 0.0072 * j.life * j.born * (0.4 + 0.6 * s.pres), 0.4);
            if (jellyV[i].pan) jellyV[i].pan.pan.value = clamp(j.x / 1.4, -1, 1);
          }
        });
        const maxCh = Math.max(...s.charge);
        A.set(nG.gain, maxCh * 0.055 + 0.002, 0.2);
        A.set(nLP.frequency, 90 + maxCh * 1500, 0.25);
        SG4_DEFS.forEach((d, i) => MOut.expr(d.role, (s.selL === i || s.selR === i) ? 0.3 + s.charge[i] * 0.7 : 0));
        const horizon = A.t() + 0.15;
        while (nextT < horizon) {
          const beatIdx = (step16 % 32) * 0.25;
          const tt = nextT;
          // each SELECTED cloud plays ITS groove on ITS grid; charge doubles the pulse
          SG4_DEFS.forEach((d, ci) => {
            const sel = (s.selL === ci || s.selR === ci) && s.spent[ci] <= 0;
            if (!sel || s.pres < 0.15) return;
            const ch = s.charge[ci];
            const lvl = ch < 0.34 ? 0 : ch < 0.72 ? 1 : 2;
            const intv = d.intv[lvl];
            if ((beatIdx % intv) > 0.001) return;
            const deg = d.lad[ladPos[ci] % d.lad.length];
            const oct = d.oct + (lvl === 2 ? 1 : 0);
            const freq = H.chordTone(deg, oct);
            const vol = 0.02 + ch * 0.035;
            const pan = clamp(d.gx * 1.2, -1, 1) * 0.6;
            if (d.role === 'bass') {
              A.bassNote(freq, { at: tt, vol: 0.06 + ch * 0.05, dur: 0.6 });
            } else if (d.role === 'bells' || d.role === 'texture') {
              A.bell(freq, { at: tt, vol: vol * 0.8, dur: d.role === 'texture' ? 3.2 : 1.1, pan, rev: 0.6 });
            } else {
              A.pluck2(freq, { at: tt, vol, dur: 0.5, pan, rev: 0.35, del: d.role === 'lead' ? 0.3 : 0.12 });
            }
            MOut.evNote(d.role, freq, 0.08 + ch * 0.1, tt, d.role === 'texture' ? 2.4 : 0.5);
            s.land[ci] = 1; ladPos[ci]++;
          });
          // strike commits on the half-bar
          if ((beatIdx % 2) < 0.001 && s.strikePend >= 0) {
            const ci = s.strikePend;
            s.strikePend = -1; s.charge[ci] = 0; s.spent[ci] = 5;
            s.strikeCloud = ci; s.strikeAt = tt;
            A.kick(tt, 0.5);
            const drop = A.ctx.createOscillator(); drop.type = 'sine';
            drop.frequency.setValueAtTime(88, tt);
            drop.frequency.exponentialRampToValueAtTime(27, tt + 0.9);
            const dg = A.ctx.createGain();
            dg.gain.setValueAtTime(0.24, tt);
            dg.gain.exponentialRampToValueAtTime(0.0001, tt + 1.1);
            drop.connect(dg); dg.connect(A.master); drop.start(tt); drop.stop(tt + 1.2);
            const th = A.ctx.createBufferSource(); th.buffer = A.noiseBuf();
            const tf = A.ctx.createBiquadFilter(); tf.type = 'lowpass'; tf.frequency.value = 420;
            const tg = A.ctx.createGain();
            tg.gain.setValueAtTime(0.0001, tt);
            tg.gain.linearRampToValueAtTime(0.30, tt + 0.05);
            tg.gain.exponentialRampToValueAtTime(0.0001, tt + 2.4);
            th.connect(tf); tf.connect(tg); tg.connect(A.master);
            if (A.revIn) { const s3 = A.ctx.createGain(); s3.gain.value = 0.8; tg.connect(s3); s3.connect(A.revIn); }
            th.start(tt); th.stop(tt + 2.5);
            MOut.evDrum(36, 0.9, tt);
            MOut.evNote('texture', H.rootFreq(-2), 0.9, tt, 2.5);
          }
          // jellies sprout on the bar with a rolled arpeggio
          if ((beatIdx % 4) < 0.001 && s.sproutReq.length) {
            const jx = s.sproutReq.shift();
            const T3 = P._three;
            if (T3 && T3.mkJelly) {
              const cols = [0xff8a3d, 0x4fd8c4, 0xa06cff, 0xffd9a0, 0xd9c8ff, 0xff6a8a];
              const j = T3.mkJelly(jx, cols[s.jellies.length % cols.length]);
              j.pulse = 1;
              s.jellies.push(j);
              [0, 1, 2].forEach(ri => {
                const freq = H.chordTone(2 + ri * 2, ri === 2 ? 1 : 0);
                A.bell(freq, { at: tt + ri * 0.08, vol: 0.042, dur: 2.6, rev: 0.75, pan: clamp(jx / 1.4, -1, 1) * 0.6 });
                MOut.evNote('pad', freq, 0.1, tt + ri * 0.08, 2.2);
              });
            }
          }
          step16++; nextT += T.beat * 0.25;
        }
        if (nextT < A.t()) nextT = T.next(0.25);
      },
      stop() { try { nsrc.stop(); } catch (e) {} v.kill(); }
    };
  }
});
})();
